import subprocess
import json
import os
import urllib.request
import urllib.error

# Download storyboard image using urllib since wget is not available
print('Downloading storyboard image for OCR analysis...')
result = subprocess.run([
    'yt-dlp',
    '-j',
    '--skip-download',
    'https://www.youtube.com/watch?v=ZCbvyPbhRfA'
], capture_output=True, text=True, timeout=30)

if result.returncode == 0:
    info = json.loads(result.stdout)
    formats = info.get('formats', [])

    # Get the highest quality storyboard
    storyboard_url = None
    for fmt in formats:
        if fmt.get('format_id') == 'sb0':  # sb0 is 160x90 (highest quality)
            if 'url' in fmt:
                storyboard_url = fmt['url']
                print(f'Found high-res storyboard (160x90)')
                break

    if not storyboard_url:
        for fmt in formats:
            if 'storyboard' in fmt.get('format', '').lower() and 'url' in fmt:
                storyboard_url = fmt['url']
                print(f'Using storyboard: {fmt.get("format")}')
                break

    if storyboard_url:
        try:
            print(f'Downloading storyboard...')
            req = urllib.request.Request(storyboard_url, headers={
                'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'
            })
            with urllib.request.urlopen(req, timeout=30) as response:
                with open('storyboard.jpg', 'wb') as f:
                    f.write(response.read())
            if os.path.exists('storyboard.jpg'):
                size = os.path.getsize('storyboard.jpg')
                print(f'Downloaded storyboard: {size} bytes')
        except Exception as e:
            print(f'Failed to download storyboard: {e}')
